class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        int ans = 0;
        for (int val = 0; val < k; val++) {
            vector<int> dp(k, 0);
            for (int x : nums) {
                int y = x % k;
                int prev = (val - y + k) % k;
                dp[y] = max(dp[y], dp[prev] + 1);
                ans = max(ans, dp[y]);
            }
        }
        return ans;
    }
};
